/**
 * Codex app-server: launch arguments, request shapes and notification mapping
 * (pure; no Electron imports). Shapes follow the protocol generated by
 * `codex app-server generate-json-schema --experimental` (codex-cli 0.169).
 *
 * Containment, verified against the real CLI:
 * - `-c` overrides turn off the shell and exec tools, image viewing and
 *   generation, plugins, apps, browser and computer use, hooks, memories,
 *   skills search, tool suggestions, goals, sub-agents (`agents.enabled`),
 *   web search, AGENTS.md project docs and history, and every MCP server the
 *   person configured (`mcp_servers.<name>.enabled=false`, names from
 *   `codex mcp list --json`). `-c` is used rather than `--disable` because a
 *   person's own `-c` would win over `--disable`.
 * - Each thread starts with `environments: []` (no execution environment, so
 *   apply_patch and any file access fail), an empty private cwd, a read-only
 *   sandbox, `approvalPolicy: "never"` and `ephemeral: true`.
 * - Every server request but `item/tool/call` is declined or refused.
 * Known gap: Codex still adds the person's global ~/.codex/AGENTS.md to the
 * instructions; no setting turns that off.
 */
import { LocalAiProxyError } from "../localAiProxy.js";
import type { CliChatRequest } from "./request.js";

export const CODEX_SIGNED_OUT = "Codex isn't signed in. Run `codex login` in Terminal, then try again.";

const CONTAINMENT_OVERRIDES = [
  "thread_unload_delay_secs=0",
  "features.plugins=false",
  "features.apps=false",
  "features.shell_tool=false",
  "features.unified_exec=false",
  "features.view_image=false",
  "features.image_generation=false",
  "features.browser_use=false",
  "features.computer_use=false",
  "features.hooks=false",
  "features.multi_agent=false",
  "features.multi_agent_v2=false",
  "features.memories=false",
  "features.skill_search=false",
  "features.tool_suggest=false",
  "features.goals=false",
  "agents.enabled=false",
  'web_search="disabled"',
  "project_doc_max_bytes=0",
  'history.persistence="none"',
];

/** `mcp_servers={}` merges, so each configured server is named; dotted names are quoted. */
export function mcpServersOff(names: readonly string[]): string | null {
  return names.length ? `mcp_servers={${names.map((name) => `${JSON.stringify(name)}={enabled=false}`).join(",")}}` : null;
}

export function codexAppServerArgs(mcpServerNames: readonly string[]): string[] {
  const off = mcpServersOff(mcpServerNames);
  return ["app-server", ...[...CONTAINMENT_OVERRIDES, ...(off ? [off] : [])].flatMap((value) => ["-c", value])];
}

/** Plugins add MCP servers of their own; list the person's with them off, as the app-server will run. */
export const CODEX_MCP_LIST_ARGS = ["-c", "features.plugins=false", "-c", "features.apps=false", "mcp", "list", "--json"];

export function parseMcpServerNames(stdout: string): string[] | null {
  try {
    const parsed: unknown = JSON.parse(stdout);
    if (!Array.isArray(parsed)) return null;
    return parsed.flatMap((entry) => {
      const name = entry && typeof entry === "object" ? (entry as Record<string, unknown>).name : undefined;
      return typeof name === "string" && name ? [name] : [];
    });
  } catch {
    return null;
  }
}

export function initializeParams(version: string) {
  return {
    clientInfo: { name: "societyer", title: "Societyer", version },
    capabilities: { experimentalApi: true, requestAttestation: false },
  };
}

export function threadStartParams(request: CliChatRequest, cwd: string) {
  return {
    cwd,
    ephemeral: true,
    environments: [],
    sandbox: "read-only",
    approvalPolicy: "never",
    // Replaces Codex's coding-agent prompt (accepted with a ChatGPT sign-in, checked on codex-cli 0.169).
    baseInstructions: request.systemPrompt,
    ...(request.model ? { model: request.model } : {}),
    ...(request.tools.length
      ? { dynamicTools: request.tools.map((tool) => ({ type: "function", name: tool.name, description: tool.description, inputSchema: tool.inputSchema })) }
      : {}),
  };
}

export function turnStartParams(threadId: string, request: CliChatRequest) {
  return {
    threadId,
    input: [{ type: "text", text: request.prompt, text_elements: [] }],
    ...(request.jsonSchema ? { outputSchema: request.jsonSchema } : {}),
  };
}

export type ServerReply = { result: unknown } | { error: { code: number; message: string } };

/**
 * The answer to a server request that isn't a Societyer tool call: decline
 * approvals and questions, refuse the rest, so a turn never waits on us.
 */
export function refuseServerRequest(method: string): ServerReply {
  switch (method) {
    case "item/commandExecution/requestApproval":
    case "item/fileChange/requestApproval":
      return { result: { decision: "decline" } };
    case "applyPatchApproval":
    case "execCommandApproval":
      return { result: { decision: { denied: { rejection: "Societyer doesn't allow this." } } } };
    case "item/tool/requestUserInput":
      return { result: { answers: {} } };
    case "mcpServer/elicitation/request":
      return { result: { action: "decline", content: null, _meta: null } };
    case "currentTime/read":
      return { result: { currentTimeAt: Math.floor(Date.now() / 1000) } };
    default:
      return { error: { code: -32601, message: "Societyer doesn't support this request." } };
  }
}

export function dynamicToolReply(content: string, isError: boolean): ServerReply {
  return { result: { contentItems: [{ type: "inputText", text: content }], success: !isError } };
}

function record(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

function errorInfoKey(info: unknown): string {
  if (typeof info === "string") return info;
  const keys = Object.keys(record(info));
  return keys[0] ?? "";
}

/** A turn's error (`TurnError`) as a plain message. */
export function codexTurnFailure(error: unknown, model: string): LocalAiProxyError {
  const turnError = record(error);
  const info = errorInfoKey(turnError.codexErrorInfo);
  const message = typeof turnError.message === "string" ? turnError.message : "";
  if (info === "unauthorized" || /log ?in|sign ?in|unauthori[sz]ed|401/i.test(message)) return new LocalAiProxyError("refused", CODEX_SIGNED_OUT);
  if (info === "usageLimitExceeded" || info === "rateLimitExceeded" || /usage limit|rate limit/i.test(message)) {
    return new LocalAiProxyError("refused", "You've reached your Codex usage limit. Try again later.");
  }
  if (info === "modelNotFound") return new LocalAiProxyError("refused", `Codex can't use the model “${model || "default"}” with this sign-in. Pick another model in On-device AI settings.`);
  if (info === "contextWindowExceeded") return new LocalAiProxyError("refused", "This conversation is too long for the model. Start a new one or send less text.");
  if (info === "serverOverloaded" || info === "internalServerError" || info.startsWith("httpConnectionFailed") || info.startsWith("responseStream")) {
    return new LocalAiProxyError("network", "OpenAI is unavailable right now. Try again in a moment.");
  }
  return new LocalAiProxyError("network", message ? `Codex couldn't answer: ${message.slice(0, 200)}` : "Codex couldn't answer. Try again.");
}

export type CodexTurnEvent = { type: "text"; text: string } | { type: "completed" } | { type: "failed"; error: LocalAiProxyError };

/**
 * Follows one turn's notifications. Text deltas of agent messages become text
 * (a new message starts a new paragraph); `turn/completed` ends it; an
 * `error` that Codex won't retry is kept for the failed turn.
 */
export class CodexTurnTracker {
  turnId: string | null = null;
  private lastError: unknown = null;
  private messages = new Map<string, string>();
  private lastItemId: string | null = null;
  private textSeen = false;

  constructor(
    readonly threadId: string,
    private readonly model: string,
  ) {}

  /** The last agent message: the answer (and the JSON for structured output). */
  finalText(): string {
    return this.lastItemId ? (this.messages.get(this.lastItemId) ?? "") : "";
  }

  notification(method: string, params: unknown): CodexTurnEvent[] {
    const p = record(params);
    if (p.threadId !== this.threadId) return [];
    const turnId = typeof p.turnId === "string" ? p.turnId : typeof record(p.turn).id === "string" ? (record(p.turn).id as string) : null;
    if (this.turnId && turnId && turnId !== this.turnId) return [];
    switch (method) {
      case "item/agentMessage/delta": {
        const itemId = typeof p.itemId === "string" ? p.itemId : "";
        const delta = typeof p.delta === "string" ? p.delta : "";
        if (!delta) return [];
        const newMessage = itemId !== this.lastItemId;
        this.messages.set(itemId, (this.messages.get(itemId) ?? "") + delta);
        this.lastItemId = itemId;
        const text = (newMessage && this.textSeen ? "\n\n" : "") + delta;
        this.textSeen = true;
        return [{ type: "text", text }];
      }
      case "item/completed": {
        const item = record(p.item);
        if (item.type === "agentMessage" && typeof item.id === "string" && typeof item.text === "string") {
          this.messages.set(item.id, item.text);
          this.lastItemId = item.id;
        }
        return [];
      }
      case "error":
        if (p.willRetry !== true) this.lastError = p.error;
        return [];
      case "turn/completed": {
        const turn = record(p.turn);
        if (turn.status === "completed") return [{ type: "completed" }];
        if (turn.status === "interrupted") return [{ type: "failed", error: new LocalAiProxyError("aborted", "The AI request was stopped.") }];
        return [{ type: "failed", error: codexTurnFailure(turn.error ?? this.lastError, this.model) }];
      }
      default:
        return [];
    }
  }
}

/** "plus" → "ChatGPT Plus"; the account email is added when known. */
export function codexAccountLabel(account: unknown): { signedIn: boolean | null; label?: string } {
  const value = record(account);
  if (value.type === "chatgpt") {
    const plan = typeof value.planType === "string" && value.planType !== "unknown" ? value.planType : "";
    const planLabel = plan ? `ChatGPT ${plan.replace(/_/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase())}` : "ChatGPT";
    return { signedIn: true, label: typeof value.email === "string" && value.email ? `${planLabel} · ${value.email}` : planLabel };
  }
  if (value.type === "apiKey") return { signedIn: true, label: "OpenAI API key" };
  if (value.type === "amazonBedrock") return { signedIn: true, label: "Amazon Bedrock" };
  if (value.type === "gcp") return { signedIn: true, label: "Google Cloud" };
  return { signedIn: false };
}

/** Visible model ids from `model/list` pages. */
export function codexModelIds(pages: unknown[]): string[] {
  const ids: string[] = [];
  for (const page of pages) {
    const data = record(page).data;
    for (const entry of Array.isArray(data) ? data : []) {
      const model = record(entry);
      const id = typeof model.id === "string" ? model.id : typeof model.model === "string" ? model.model : "";
      if (id && model.hidden !== true) ids.push(id);
    }
  }
  return [...new Set(ids)];
}
